import{Z as a,e as t,f as s,a0 as i}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Payment","description":"","frontmatter":{},"headers":[],"relativePath":"fields/payment.md","filePath":"fields/payment.md","lastUpdated":1782532814000}'),n={name:"fields/payment.md"};function r(o,e,l,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="payment" tabindex="-1">Payment <a class="header-anchor" href="#payment" aria-label="Permalink to &quot;Payment&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For a full Stripe checkout walkthrough, see <a href="/guides/fields/payment-field-with-stripe-full-flow">Payment field with Stripe — full flow</a>.</p></div><p>Use Payment when the form should collect or authorize a payment</p><p>Use Payment when the form itself is responsible for taking payment. If the project already has a full checkout flow, it may be better to keep payment there and link the form to that process.</p><h2 id="take-a-test-payment" tabindex="-1">Take a Test Payment <a class="header-anchor" href="#take-a-test-payment" aria-label="Permalink to &quot;Take a Test Payment&quot;">​</a></h2><p>Start with a form containing a Payment field and connect a provider using its setup page below. Configure the amount and currency, then use the provider’s test environment to complete the form. Inspect both the saved submission and the provider’s transaction before using live credentials. Also test a declined or cancelled payment; the confirmation shown to the visitor must match the actual payment outcome.</p><h2 id="key-settings" tabindex="-1">Key Settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to &quot;Key Settings&quot;">​</a></h2><ul><li><strong>Payment integration</strong> - Choose the provider used by this field.</li><li><strong>Amount and currency</strong> - Configure the amount to charge or authorize.</li><li><strong>Billing details</strong> - Map form fields into the payment provider’s expected customer or billing data.</li><li><strong>Provider behavior</strong> - Configure provider-specific settings such as hosted UI, tokenization or redirects.</li><li><strong>Submission behavior</strong> - Account for any Ajax or workflow requirements surfaced by the provider.</li></ul><h2 id="submitted-value" tabindex="-1">Submitted Value <a class="header-anchor" href="#submitted-value" aria-label="Permalink to &quot;Submitted Value&quot;">​</a></h2><p>Payment stores payment-related submission data rather than normal text input. The exact value and records depend on the configured provider and whether the payment is authorized, captured, redirected or reconciled later.</p><p>When querying or saving submissions through GraphQL, payment behaviour depends on the provider and submission workflow. Query the form’s <code>formFields</code> and include <code>inputTypeName</code> when building a custom front end.</p><h2 id="payment-providers" tabindex="-1">Payment Providers <a class="header-anchor" href="#payment-providers" aria-label="Permalink to &quot;Payment Providers&quot;">​</a></h2><p>Payment providers are configured in two places:</p><ol><li>Create and configure a payment integration in <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Edit the Payment field, then choose the provider for <strong>Payment Integration</strong>.</li></ol><p>Provider setup is documented on the payment integration pages:</p><ul><li><a href="/integrations/payments/bpoint">BPOINT</a></li><li><a href="/integrations/payments/eway">eWAY</a></li><li><a href="/integrations/payments/gocardless">GoCardless</a></li><li><a href="/integrations/payments/mollie">Mollie</a></li><li><a href="/integrations/payments/moneris">Moneris</a></li><li><a href="/integrations/payments/opayo">Opayo</a></li><li><a href="/integrations/payments/paddle">Paddle</a></li><li><a href="/integrations/payments/paypal">PayPal</a></li><li><a href="/integrations/payments/westpac-payway">PayWay</a></li><li><a href="/integrations/payments/square">Square</a></li><li><a href="/integrations/payments/stripe">Stripe</a></li></ul><p>Payment behaviour depends on the selected provider. Some providers use hosted payment UI, some tokenize card details in the browser, and some complete payment through redirects or webhook updates. If you are building a custom provider, see <a href="/developers/custom-integration/payment-integration">Payment Integration</a>.</p><h2 id="theme-config" tabindex="-1">Theme Config <a class="header-anchor" href="#theme-config" aria-label="Permalink to &quot;Theme Config&quot;">​</a></h2><p>The Payment field can be targeted with the <code>payment</code> theme config key.</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    themeConfig: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        payment: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            field: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                attributes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    class: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-payment-field&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            stripePlaceholder: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                attributes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    class: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-stripe-placeholder&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>Use theme config for surrounding markup and attributes. Be careful with template overrides because payment providers may require specific elements or scripts.</p><p>For full Tailwind, Bootstrap and other framework examples, see <a href="https://github.com/verbb/formie-theme-configs" target="_blank" rel="noreferrer">Formie theme configs</a>.</p><h2 id="front-end-reference" tabindex="-1">Front-End Reference <a class="header-anchor" href="#front-end-reference" aria-label="Permalink to &quot;Front-End Reference&quot;">​</a></h2><p>Payment fields often depend on provider JavaScript, Ajax submission, redirects or webhook reconciliation. If you customise rendering, keep the provider’s required front-end assets and submission flow intact.</p><p>The front-end docs live on the separate browser UI reference site and cover rendered markup, data attributes, styling classes and JavaScript behaviour for custom front-end implementations.</p><ul><li><a href="https://docs.verbb.io/formie/browser/ui-reference/fields/payment" target="_blank" rel="noreferrer">Payment</a></li></ul><h2 id="related-fields" tabindex="-1">Related Fields <a class="header-anchor" href="#related-fields" aria-label="Permalink to &quot;Related Fields&quot;">​</a></h2><ul><li>Use <a href="/fields/products">Products</a> or <a href="/fields/variants">Variants</a> when the form should select Commerce elements.</li><li>Use <a href="/fields/calculations">Calculations</a> when the payment amount is derived from other field values.</li></ul><h2 id="recover-unresolved-payments" tabindex="-1">Recover Unresolved Payments <a class="header-anchor" href="#recover-unresolved-payments" aria-label="Permalink to &quot;Recover Unresolved Payments&quot;">​</a></h2><p>If a visitor sees an unresolved payment after a timeout, check the gateway before asking them to pay again. Your developer can use the <a href="/developers/console-commands#recover-payments">payment recovery commands</a> to inspect the saved attempt, verify its outcome and resume a successful submission.</p>`,30)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
